\solution{Corrigé -- Exercice 1}
\begin{center}\small
\begin{tabular}{rrrrr}
\toprule
$x$&$y$&$x^2$&$y^2$&$xy$\\\midrule
5&9&25&81&45\\
6&10&36&100&60\\
7&14&49&196&98\\
9&16&81&256&144\\
8&19&64&361&152\\
11&20&121&400&220\\
12&23&144&529&276\\
13&26&169&676&338\\
14&29&196&841&406\\
16&32&256&1024&512\\\midrule
$\sum$&$\sum x=101$&$\sum y=198$&$\sum x^2=1141$&$\sum y^2=4464$, $\sum xy=2251$\\
\bottomrule
\end{tabular}
\end{center}
Avec $N=10$ :
\[
\bar x=10,1,\qquad \bar y=19,8.
\]
\[
V(x)=1141/10-(10,1)^2=114,1-102,01=\boxed{12,09},
\]
\[
V(y)=4464/10-(19,8)^2=446,4-392,04=\boxed{54,36}.
\]
\[
\sigma_x=\sqrt{12,09}=3,477,\qquad \sigma_y=\sqrt{54,36}=7,373.
\]
\[
Cov(x,y)=2251/10-(10,1)(19,8)=225,1-199,98=\boxed{25,12}.
\]
\[
R=\frac{25,12}{(3,477)(7,373)}=\boxed{0,9799}.
\]
Comme $|R|\geq0,86$, le cours conduit à conclure à une \textbf{bonne corrélation linéaire positive}.

La convention du cours est $\hat y=ax+b$ :
\[
a=\frac{Cov(x,y)}{V(x)}=\frac{25,12}{12,09}=\boxed{2,07775},
\]
\[
b=\bar y-a\bar x=19,8-2,07775(10,1)=\boxed{-1,18528}.
\]
Donc
\[
\boxed{\hat y=2,07775x-1,18528}.
\]
Pour 3000 clients, $x=30$ :
\[
\hat y=2,07775(30)-1,18528=61,1472.
\]
Comme $y$ est en $10^4$ euros :
\[
CA\approx61,1472\times10^4=\boxed{611\,472\ \text{euros}}.
\]
\begin{center}
\begin{tikzpicture}
\begin{axis}[width=.72\linewidth,height=6cm,xlabel={$x$ (centaines de clients)},ylabel={$y$ ($10^4$ euros)},grid=major]
\addplot[only marks,mark=*] coordinates {(5,9)(6,10)(7,14)(9,16)(8,19)(11,20)(12,23)(13,26)(14,29)(16,32)};
\addplot[domain=4:17] {2.07775*x-1.18528};
\end{axis}
\end{tikzpicture}
\end{center}

\solution{Corrigé -- Exercice 2}
Pour $t=1,\ldots,10$ : $\bar t=5,5$ et
\[
V(t)=\frac{385}{10}-(5,5)^2=38,5-30,25=8,25.
\]
On a $\sum tx=654$, donc
\[
Cov(t,x)=654/10-(5,5)(10,1)=65,4-55,55=9,85.
\]
\[
R(t,x)=\frac{9,85}{\sqrt{8,25}\sqrt{12,09}}=\boxed{0,9863}.
\]
La droite est
\[
a=9,85/8,25=1,19394,\qquad b=10,1-1,19394(5,5)=3,53333,
\]
soit
\[
\boxed{\hat x=1,19394t+3,53333}.
\]
En 2016, $t=12$ :
\[
\hat x=1,19394(12)+3,53333=17,8606,
\]
soit environ \boxed{1786\ \text{clients}}.
On injecte cette valeur dans la droite $y$ sur $x$ :
\[
\hat y=2,07775(17,8606)-1,18528=35,9246,
\]
soit environ
\[
\boxed{359\,246\ \text{euros}}.
\]

\solution{Corrigé -- Exercice 3}
Comme dans le support, le premier sous-nuage contient les trois premiers points et le second les deux derniers.
\[
A=\left(\frac{1+2+3}{3},\frac{7+10+10}{3}\right)=(2,9),
\]
\[
B=\left(\frac{4+5}{2},\frac{14+14}{2}\right)=(4,5,14).
\]
La droite passant par $A$ et $B$ a pour pente
\[
a=\frac{14-9}{4,5-2}=\frac5{2,5}=2.
\]
Puis $9=2(2)+b$, donc $b=5$. La droite de Mayer est
\[
\boxed{y=2x+5}.
\]

